@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Oswald:wght@500;600;700&display=swap');
:root{--bg:#101513;--panel:#171d1a;--panel2:#1d2521;--line:#303a34;--muted:#87928a;--text:#e5e9e2;--lime:#c0d889;--orange:#d49b5b;--red:#cf6d60;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif;--display:'Oswald',sans-serif}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 48% 0%,#1a211d 0,#101513 62%);color:var(--text);font-family:var(--sans);min-height:100vh}.game-shell{max-width:1600px;margin:auto;padding:0 28px}.topbar{height:74px;border-bottom:1px solid #29312d;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;gap:11px;align-items:center;color:var(--text);text-decoration:none;font:600 19px var(--display);letter-spacing:1.9px}.brand small{display:block;color:#839087;font:9px var(--mono);letter-spacing:2.2px;margin-top:1px}.brand-mark{display:grid;place-items:center;width:34px;height:34px;background:#c0d889;color:#182019;font:700 21px var(--display);clip-path:polygon(50% 0,100% 100%,0 100%);padding-top:7px}.world-status{display:flex;align-items:center;gap:10px;font:10px var(--mono);letter-spacing:1.25px;color:#a6afa7}.world-status i{height:13px;width:1px;background:#3a443e;margin:0 3px}.live-dot,.condition i,.turn-indicator i{width:7px;height:7px;border-radius:50%;background:#a5c974;box-shadow:0 0 8px #a5c974;display:inline-block}.top-actions{display:flex;gap:8px}.icon-button,.dots-button{height:32px;width:34px;border:1px solid #333d37;background:#171d1a;color:#9da89e;border-radius:4px;font:14px var(--mono);cursor:pointer}.icon-button:hover,.map-button:hover{border-color:var(--lime);color:var(--lime)}.game-layout{display:grid;grid-template-columns:244px minmax(420px,1fr) 276px;gap:17px;padding:20px 0 15px;min-height:calc(100vh - 122px)}.panel{background:linear-gradient(150deg,#1a211d 0%,#161c19 100%);border:1px solid #303a34;border-radius:5px;min-width:0;box-shadow:0 12px 30px #00000012}.survivor-panel,.intel-panel{padding:16px 15px;display:flex;flex-direction:column}.panel-heading{font:500 10px var(--mono);letter-spacing:1.5px;color:#a3ada4;display:flex;justify-content:space-between;align-items:center}.tiny-tag{border:1px solid #3a463d;padding:4px 6px;font:9px var(--mono);color:#909b91}.tiny-tag b{color:var(--lime);margin-left:3px}.survivor-card{display:flex;gap:12px;align-items:center;margin-top:20px}.portrait{width:62px;height:72px;background:linear-gradient(145deg,#394a3d,#202a24 70%);border:1px solid #566448;position:relative;display:grid;place-items:center;overflow:hidden;color:#c4d29f;font-size:33px}.portrait:before{content:'';position:absolute;inset:8px 11px 18px;border:1px solid #71815d;border-radius:45% 45% 30% 30%;opacity:.48}.portrait-scan{position:absolute;height:1px;background:#bacd81aa;left:0;right:0;top:25px;box-shadow:0 0 8px #c0d889}.portrait-status{position:absolute;bottom:0;left:0;right:0;text-align:center;background:#111713;font:8px var(--mono);letter-spacing:1px;color:#b8d180;padding:4px}.survivor-info{display:flex;flex-direction:column;gap:5px}.survivor-info strong{font-size:13px;font-weight:600}.survivor-info small{font:8px var(--mono);letter-spacing:.7px;color:#879188}.condition{display:flex;gap:6px;align-items:center;margin-top:5px;font:9px var(--mono);color:#b4bfaf}.condition i{width:5px;height:5px}.vitals{display:grid;gap:13px;margin:21px 0 19px}.vital-label{display:flex;align-items:center;font:9px var(--mono);letter-spacing:.6px;color:#9ca69e;margin-bottom:6px}.vital-label span{width:17px;font-size:12px;color:#c1d58e}.vital-label b{margin-left:auto;color:#d6ddd4;font-weight:400}.meter{height:4px;background:#303a34;border-radius:3px;overflow:hidden}.meter i{height:100%;display:block;border-radius:3px;transition:width .25s}.health-fill{background:#d37969}.stamina-fill{background:#a8c976}.hunger-fill{background:#d9a25e}.thirst-fill{background:#79b2ac}.divider{height:1px;background:#303a34;margin-bottom:17px}.section-title,.nearby-heading,.log-heading{font:9px var(--mono);letter-spacing:1.35px;color:#aab3aa;display:flex;justify-content:space-between;align-items:center}.section-title span{font-size:8px;letter-spacing:.3px;color:#79847c}.inventory-list{margin-top:11px;display:flex;flex-direction:column;gap:2px}.item-row{display:flex;align-items:center;gap:9px;padding:8px 5px;border-bottom:1px solid #28312c}.item-icon{width:27px;height:27px;background:#252e28;border:1px solid #354239;display:grid;place-items:center;color:#c5d492;font-size:13px;border-radius:3px}.item-copy{min-width:0;flex:1}.item-copy b{font-size:10px;font-weight:500;display:block}.item-copy small{font:8px var(--mono);color:#7f8a81}.item-qty{font:10px var(--mono);color:#bac88e}.inventory-empty{font:10px var(--mono);color:#728076;padding:14px 5px}.panel-bottom{margin-top:auto;padding-top:14px;display:flex;align-items:center;gap:8px;font:8px var(--mono);letter-spacing:1px;color:#758078}.weight-track{height:3px;background:#303a34;flex:1}.weight-track i{height:100%;display:block;width:20%;background:#afc87d}.center-column{min-width:0;display:flex;flex-direction:column}.map-toolbar{height:56px;display:flex;justify-content:space-between;align-items:flex-start;padding:1px 2px 12px}.location{display:flex;align-items:center;gap:10px}.location-pin{width:32px;height:32px;display:grid;place-items:center;border:1px solid #414b40;color:var(--lime);font-size:20px;border-radius:3px}.location b{display:block;font:600 13px var(--display);letter-spacing:1.2px}.location small{display:block;font:8px var(--mono);color:#859087;letter-spacing:.8px;margin-top:3px}.map-tools{display:flex;align-items:center;gap:12px}.threat-level{display:flex;align-items:center;gap:3px}.threat-level i{width:3px;height:9px;background:#738653;display:block}.threat-level i:last-of-type{background:#323d34}.threat-level b{font:8px var(--mono);letter-spacing:.4px;color:#9baa83;margin-left:4px}.map-button{background:#171d1a;border:1px solid #344038;color:#9ca89d;font:8px var(--mono);letter-spacing:.7px;padding:8px 10px;border-radius:3px;cursor:pointer}.map-frame{position:relative;flex:1;min-height:430px;overflow:hidden;background:#243329;border:1px solid #465044;border-radius:4px;box-shadow:0 10px 40px #0005}.map-frame canvas{display:block;width:100%;height:100%;image-rendering:pixelated}.map-vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 42%,#0b100eb0 100%);box-shadow:inset 0 0 0 1px #d5e0bb14}.map-compass{position:absolute;top:15px;right:16px;width:31px;height:39px;border:1px solid #bec7aa55;background:#151c1999;text-align:center;color:#ccd4bb}.map-compass span{font:8px var(--mono);display:block;margin-top:4px;color:#a7b394}.map-compass b{font:17px var(--sans);line-height:14px}.map-hint{position:absolute;bottom:13px;left:50%;transform:translateX(-50%);white-space:nowrap;background:#131916cf;border:1px solid #aeb8a626;border-radius:3px;padding:8px 11px;color:#b1bbb0;font:8px var(--mono);letter-spacing:.7px}.map-hint span{color:#d2dfa7}.map-hint i{color:#758176;font-style:normal;padding:0 5px}.toast{position:absolute;top:20px;left:50%;transform:translate(-50%,-12px);background:#d4e4ae;color:#1b241b;padding:9px 14px;border-radius:3px;font:10px var(--mono);opacity:0;transition:.25s;pointer-events:none;white-space:nowrap;z-index:3}.toast.show{opacity:1;transform:translate(-50%,0)}.quickbar{height:55px;display:flex;align-items:center;gap:5px;margin-top:10px;border-top:1px solid #29322d;padding-top:9px}.quick-label{font:8px var(--mono);letter-spacing:1px;color:#77827a;margin-right:4px;white-space:nowrap}.quickbar button{height:33px;display:flex;gap:7px;align-items:center;padding:0 8px;background:#1a211d;border:1px solid #313a34;border-radius:3px;color:#c0c8bf;cursor:pointer;font:8px var(--mono);letter-spacing:.6px}.quickbar button:hover{border-color:#9caf73;color:#d8e6b3;background:#242d26}.quickbar kbd{font:9px var(--mono);color:#9ead7d;border:1px solid #4a5844;border-radius:2px;padding:3px 4px}.turn-indicator{margin-left:auto;display:flex;align-items:center;gap:6px;font:8px var(--mono);letter-spacing:.8px;color:#78837a;white-space:nowrap}.turn-indicator i{width:5px;height:5px}.turn-indicator b{color:#d0d8c8;font-weight:400}.intel-panel{padding:15px 14px}.dots-button{border:0;background:none;height:auto;width:auto;font:12px var(--mono);letter-spacing:2px}.objective-card{margin-top:17px;padding:14px 13px 12px;background:linear-gradient(145deg,#263229,#202922);border:1px solid #3b493c;border-left:2px solid #b5ce7e;border-radius:3px}.objective-kicker{display:flex;justify-content:space-between;align-items:center;color:#9cac81;font:8px var(--mono);letter-spacing:1.2px}.objective-icon{font-size:16px;color:#c0d889}.objective-card h2{font:600 19px/1.2 var(--display);letter-spacing:.2px;margin:9px 0 6px;color:#e4e9dc}.objective-card p{font-size:10px;line-height:1.55;color:#a5afa4;margin:0}.objective-progress{margin-top:14px}.objective-progress>span{display:block;font:8px var(--mono);letter-spacing:.7px;color:#a2ad9e;margin-bottom:6px}.objective-progress div{height:3px;background:#3a453c}.objective-progress i{width:14%;height:100%;display:block;background:#b9d282}.nearby-heading{margin:19px 0 8px}.nearby-heading span:last-child{font:9px var(--mono);color:#8e9a8d}.nearby-list{display:flex;flex-direction:column;gap:6px}.nearby-item{display:flex;align-items:center;gap:9px;background:#202722;border:1px solid #303a34;padding:8px;border-radius:3px}.nearby-symbol{height:29px;width:29px;background:#2c372e;display:grid;place-items:center;color:#c4d695;border-radius:2px;font-size:14px}.nearby-copy{flex:1}.nearby-copy b{display:block;font-size:9px;font-weight:500}.nearby-copy small{font:8px var(--mono);color:#7f8b81}.distance{font:8px var(--mono);color:#9fac83}.empty-nearby{padding:13px 4px;color:#748076;font:9px var(--mono)}.log-heading{border-top:1px solid #303a34;padding-top:13px;margin-top:15px}.log-heading button{background:none;border:0;color:#7e8a7f;font:8px var(--mono);cursor:pointer}.event-log{height:115px;overflow:auto;margin-top:7px;display:flex;flex-direction:column;gap:8px;padding:3px 2px}.log-line{font-size:9px;line-height:1.4;color:#9ca79c;display:flex;gap:7px}.log-line time{font:8px var(--mono);color:#75817a;white-space:nowrap}.log-line b{color:#c3d394;font-weight:500}.radio-card{margin-top:auto;background:#202824;border:1px solid #343e37;display:flex;gap:8px;align-items:center;padding:9px;border-radius:3px}.radio-icon{color:#b8cd84;font-size:15px}.radio-card b{font:8px var(--mono);letter-spacing:.5px;color:#b6c0b3}.radio-card p{font:8px/1.4 var(--mono);color:#78847b;margin:4px 0 0}.signal{font:11px var(--mono);color:#a7bf79;align-self:flex-end}.footer{height:28px;border-top:1px solid #29312d;display:flex;justify-content:space-between;align-items:center;color:#68736b;font:8px var(--mono);letter-spacing:.8px}.footer span:nth-child(2){color:#879a72}.footer i{display:inline-block;width:5px;height:5px;background:#a5c974;border-radius:50%;margin-right:5px}.modal-backdrop{position:fixed;inset:0;z-index:10;display:grid;place-items:center;background:#090d0bdd;padding:16px}.modal-backdrop.hidden{display:none}.modal{width:min(450px,100%);max-height:85vh;overflow:auto;position:relative;background:#1a211d;border:1px solid #485345;border-radius:5px;padding:25px;box-shadow:0 20px 80px #000b}.modal-close{position:absolute;right:13px;top:10px;border:0;background:none;color:#aab5a8;font-size:23px;cursor:pointer}.modal h2{font:600 23px var(--display);letter-spacing:.8px;margin:0 0 6px}.modal-kicker{font:9px var(--mono);letter-spacing:1.3px;color:#afc77f;margin-bottom:12px}.modal p{color:#a8b2a8;font-size:12px;line-height:1.6}.modal-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:18px}.modal-actions button,.action-button{background:#b8ce84;border:1px solid #c8d996;color:#192119;padding:10px 13px;border-radius:3px;font:10px var(--mono);letter-spacing:.6px;cursor:pointer}.modal-actions button.secondary{background:#222a24;color:#c0cbb6;border-color:#485346}.recipe{border:1px solid #333e35;background:#202822;padding:12px;margin:8px 0;display:flex;justify-content:space-between;align-items:center}.recipe b{font-size:11px}.recipe small{display:block;color:#899589;font:9px var(--mono);margin-top:4px}.recipe button{font:9px var(--mono);padding:7px 9px;background:#b8ce84;border:0;color:#1b241b;cursor:pointer}.recipe button:disabled{background:#384139;color:#7d877b;cursor:not-allowed}.help-grid{display:grid;grid-template-columns:auto 1fr;gap:9px 14px;font-size:11px;color:#aab4aa}.help-grid kbd{font:9px var(--mono);color:#c5d78f;border:1px solid #4a5744;padding:3px 5px;border-radius:2px;white-space:nowrap}
@media(max-width:1120px){.game-shell{padding:0 16px}.game-layout{grid-template-columns:220px minmax(380px,1fr);}.intel-panel{grid-column:1 / -1;display:grid;grid-template-columns:1fr 1fr 1fr;gap:0 15px}.intel-panel>.panel-heading{grid-column:1/-1}.objective-card{grid-column:1;grid-row:2/5;margin-top:12px}.nearby-heading{grid-column:2;grid-row:2;margin:13px 0 8px}.nearby-list{grid-column:2;grid-row:3/5}.log-heading{grid-column:3;grid-row:2;margin-top:13px}.event-log{grid-column:3;grid-row:3/5;height:100px}.radio-card{grid-column:1/-1;margin-top:12px}.game-layout{min-height:0}.map-frame{min-height:460px}}
@media(max-width:760px){.game-shell{padding:0 10px}.topbar{height:60px}.world-status{font-size:8px;gap:6px;letter-spacing:.7px}.world-status i{height:10px}.brand{font-size:16px}.brand-mark{height:30px;width:30px}.top-actions{gap:4px}.icon-button{width:29px;height:29px}.game-layout{grid-template-columns:1fr;gap:10px;padding-top:12px}.center-column{grid-row:1}.map-toolbar{height:48px}.map-frame{min-height: min(63vh,520px)}.quickbar{overflow-x:auto}.quick-label{display:none}.quickbar button{flex:1;justify-content:center;min-width:61px;padding:0 5px}.turn-indicator{display:none}.survivor-panel{grid-row:2;display:grid;grid-template-columns:1fr 1fr;gap:0 12px;padding:13px}.survivor-panel>.panel-heading{grid-column:1/-1}.survivor-card{grid-column:1;grid-row:2;margin-top:12px}.vitals{grid-column:2;grid-row:2/4;margin:12px 0 0;gap:9px}.divider{grid-column:1/-1;margin:13px 0}.section-title{grid-column:1/-1}.inventory-list{grid-column:1/-1;display:grid;grid-template-columns:1fr 1fr}.inventory-list .item-row{padding:6px 3px}.panel-bottom{grid-column:1/-1;margin-top:8px;padding-top:8px}.intel-panel{display:flex;}.objective-card{margin-top:12px}.nearby-heading{margin-top:16px}.event-log{height:95px}.radio-card{margin-top:15px}.map-hint{font-size:7px;padding:7px 8px}.footer{font-size:7px}.footer span:last-child{display:none}}
@media(max-width:390px){.world-status{display:none}.topbar{justify-content:space-between}.threat-level{display:none}.map-tools{gap:3px}.quickbar button{font-size:7px;gap:4px}.quickbar kbd{font-size:8px}.survivor-info strong{font-size:11px}}

(() => {
  'use strict';
  const canvas = document.getElementById('game-canvas');
  const ctx = canvas.getContext('2d');
  const W = 64, H = 64;
  const player = {x:30,y:31,hp:100,stamina:100,hunger:12,thirst:18};
  const state = {turn:0,day:1,hour:12,paused:false,zoom:false,dead:false,won:false,searches:0,killCount:0,inventory:{'Water bottle':2,'Canned beans':2,'Bandage':1,'Pocket knife':1},items:{'Water bottle':{icon:'◉',type:'drink',weight:.6},'Canned beans':{icon:'▤',type:'food',weight:.4},'Bandage':{icon:'✚',type:'heal',weight:.2},'Pocket knife':{icon:'⌁',type:'weapon',weight:.4},'Scrap metal':{icon:'⬟',type:'material',weight:.8},'Cloth':{icon:'▧',type:'material',weight:.3},'Pine branch':{icon:'⌇',type:'material',weight:.5},'Jerky':{icon:'▰',type:'food',weight:.3},'Wooden spear':{icon:'↗',type:'weapon',weight:1.2}},logs:[],toastTimer:null};
  const tile = Array.from({length:H},()=>Array(W).fill('grass'));
  const structures = [
    {x:34,y:26,w:7,h:6,type:'house',name:'Pine Ridge Cabin'},
    {x:20,y:37,w:7,h:5,type:'store',name:'Corner Market'},
    {x:40,y:39,w:8,h:6,type:'house',name:'Abandoned Home'},
    {x:16,y:20,w:6,h:5,type:'shed',name:'Tool Shed'}
  ];
  const loot = [
    {x:37,y:29,name:'Cabin supply crate',icon:'▣',desc:'A weather-beaten crate tucked under the porch.',contents:{'Canned beans':2,'Water bottle':1,'Cloth':1}},
    {x:23,y:39,name:'Corner market',icon:'▤',desc:'The front window is already broken. Something rustles inside.',contents:{'Jerky':2,'Water bottle':1,'Bandage':1}},
    {x:44,y:42,name:'Abandoned home',icon:'⌂',desc:'A quiet house with the front door hanging open.',contents:{'Canned beans':1,'Scrap metal':1,'Pine branch':2}},
    {x:18,y:22,name:'Tool shed',icon:'⚒',desc:'A little shed, still locked. The door gives way with a groan.',contents:{'Scrap metal':2,'Pine branch':2,'Pocket knife':1}},
    {x:27,y:28,name:'Overturned daypack',icon:'▣',desc:'A battered pack sits in the roadside grass.',contents:{'Water bottle':1,'Jerky':1,'Cloth':1}}
  ];
  const zombies = [
    {x:35,y:33,hp:2,name:'Shambler',id:1},
    {x:25,y:32,hp:2,name:'Shambler',id:2},
    {x:42,y:34,hp:2,name:'Shambler',id:3},
    {x:32,y:20,hp:2,name:'Shambler',id:4}
  ];
  const decor = [];
  const hash=(x,y)=>{let n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)};
  function inside(x,y){return x>=0&&y>=0&&x<W&&y<H}
  function isRoad(x,y){return (x>=29&&x<=31)||(y>=30&&y<=32)}
  function initWorld(){
    for(let y=0;y<H;y++)for(let x=0;x<W;x++){
      let t='grass',r=hash(x,y);
      if(isRoad(x,y))t='road'; else if(r>.83)t='bush'; else if(r>.72)t='tree'; else if(r<.025)t='flower';
      if(x<2||y<2||x>W-3||y>H-3)t='water';
      tile[y][x]=t;
      if(r>.25)decor.push({x,y,v:hash(x+83,y+13)});
    }
    for(const s of structures){for(let y=s.y;y<s.y+s.h;y++)for(let x=s.x;x<s.x+s.w;x++)tile[y][x]=(x===s.x||x===s.x+s.w-1||y===s.y||y===s.y+s.h-1)?'wall':(y===s.y+s.h-1&&x===s.x+Math.floor(s.w/2)?'door':'floor');s.kind=s.type;}
    // small roadside trees and wreckage establish a readable trail into town
    for(const [x,y] of [[27,25],[32,26],[28,35],[33,36],[16,31],[39,31],[44,31],[21,33],[36,36]])tile[y][x]='tree';
  }
  initWorld();
  function tileAt(x,y){return inside(x,y)?tile[y][x]:'water'}
  function blocked(x,y){const t=tileAt(x,y);return t==='tree'||t==='water'||t==='wall'}
  function enemyAt(x,y){return zombies.find(z=>z.hp>0&&z.x===x&&z.y===y)}
  function lootAt(x,y){return loot.find(l=>!l.opened&&Math.abs(l.x-x)<=1&&Math.abs(l.y-y)<=1)}
  function timeText(){let hr=state.hour%24;let suffix=hr>=12?'PM':'AM';let h=hr%12||12;return `${String(h).padStart(2,'0')}:00 ${suffix}`}
  function addLog(text,important=false){const stamp=timeText();state.logs.unshift({text,stamp,important});state.logs=state.logs.slice(0,7);renderLog()}
  function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),1800)}
  function addItem(name,n=1){state.inventory[name]=(state.inventory[name]||0)+n;renderInventory()}
  function removeItem(name,n=1){if((state.inventory[name]||0)<n)return false;state.inventory[name]-=n;if(!state.inventory[name])delete state.inventory[name];renderInventory();return true}
  function renderInventory(){
    const el=document.getElementById('inventory');const entries=Object.entries(state.inventory);el.innerHTML=entries.length?entries.map(([name,count])=>{const it=state.items[name]||{icon:'◆',weight:.5};return `<div class="item-row" title="Click to use ${name}" data-item="${name}"><span class="item-icon">${it.icon}</span><span class="item-copy"><b>${name}</b><small>${(it.weight*count).toFixed(1)} kg · ${it.type}</small></span><span class="item-qty">×${count}</span></div>`}).join(''):'<div class="inventory-empty">Nothing but dust.</div>';
    el.querySelectorAll('.item-row').forEach(row=>row.addEventListener('click',()=>useItem(row.dataset.item)));
    const weight=Object.entries(state.inventory).reduce((a,[n,c])=>a+(state.items[n]?.weight||.5)*c,0);document.getElementById('weight-label').textContent=`${weight.toFixed(1)} / 22 kg`;document.querySelector('.weight-track i').style.width=`${Math.min(100,weight/22*100)}%`;
  }
  function renderLog(){document.getElementById('event-log').innerHTML=state.logs.map(x=>`<div class="log-line"><time>${x.stamp}</time><span>${x.important?'<b>!</b> ':''}${x.text}</span></div>`).join('')}
  function renderNearby(){
    const things=[];for(const z of zombies){let d=Math.abs(z.x-player.x)+Math.abs(z.y-player.y);if(z.hp>0&&d<=8)things.push({d,icon:'♟',name:z.name,sub:'MOVING · HOSTILE',color:'danger'})}
