(() => {
'use strict';
const canvas=document.getElementById('game-canvas'),ctx=canvas.getContext('2d'),W=64,H=64;
const player={x:30,y:31,hp:100,stamina:100,hunger:12,thirst:18};
const state={turn:0,day:1,hour:12,paused:false,zoom:false,dead:false,won:false,searches:0,killCount:0,inventory:{'Water bottle':2,'Canned beans':2,'Bandage':1,'Pocket knife':1},items:{'Water bottle':{icon:'◉',type:'drink',weight:.6},'Canned beans':{icon:'▤',type:'food',weight:.4},'Bandage':{icon:'✚',type:'heal',weight:.2},'Pocket knife':{icon:'⌁',type:'weapon',weight:.4},'Scrap metal':{icon:'⬟',type:'material',weight:.8},'Cloth':{icon:'▧',type:'material',weight:.3},'Pine branch':{icon:'⌇',type:'material',weight:.5},'Jerky':{icon:'▰',type:'food',weight:.3},'Wooden spear':{icon:'↗',type:'weapon',weight:1.2}},logs:[],toastTimer:null};
const tiles=Array.from({length:H},()=>Array(W).fill('grass'));
const structures=[{x:34,y:26,w:7,h:6,type:'house'},{x:20,y:37,w:7,h:5,type:'store'},{x:40,y:39,w:8,h:6,type:'house'},{x:16,y:20,w:6,h:5,type:'shed'}];
const loot=[{x:37,y:29,name:'Cabin supply crate',icon:'▣',desc:'A weather-beaten crate tucked under the porch.',contents:{'Canned beans':2,'Water bottle':1,'Cloth':1}},{x:23,y:39,name:'Corner market',icon:'▤',desc:'The front window is already broken. Something rustles inside.',contents:{'Jerky':2,'Water bottle':1,'Bandage':1}},{x:44,y:42,name:'Abandoned home',icon:'⌂',desc:'A quiet house with the front door hanging open.',contents:{'Canned beans':1,'Scrap metal':1,'Pine branch':2}},{x:18,y:22,name:'Tool shed',icon:'⚒',desc:'A little shed, still locked. The door gives way with a groan.',contents:{'Scrap metal':2,'Pine branch':2,'Pocket knife':1}},{x:27,y:28,name:'Overturned daypack',icon:'▣',desc:'A battered pack sits in the roadside grass.',contents:{'Water bottle':1,'Jerky':1,'Cloth':1}}];
const zombies=[{x:35,y:33,hp:2,id:1,name:'Shambler'},{x:25,y:32,hp:2,id:2,name:'Shambler'},{x:42,y:34,hp:2,id:3,name:'Shambler'},{x:32,y:20,hp:2,id:4,name:'Shambler'}];
const hash=(x,y)=>{const n=Math.sin(x*127.1+y*311.7)*43758.5453;return n-Math.floor(n)};
function inside(x,y){return x>=0&&y>=0&&x<W&&y<H}function tileAt(x,y){return inside(x,y)?tiles[y][x]:'water'}
function isRoad(x,y){return x>=29&&x<=31||y>=30&&y<=32}
function initWorld(){for(let y=0;y<H;y++)for(let x=0;x<W;x++){const r=hash(x,y);tiles[y][x]=x<2||y<2||x>W-3||y>H-3?'water':isRoad(x,y)?'road':r>.83?'bush':r>.72?'tree':r<.025?'flower':'grass'};for(const s of structures){for(let y=s.y;y<s.y+s.h;y++)for(let x=s.x;x<s.x+s.w;x++)tiles[y][x]=(y===s.y+s.h-1&&x===s.x+Math.floor(s.w/2))?'door':(x===s.x||x===s.x+s.w-1||y===s.y||y===s.y+s.h-1)?'wall':'floor'}for(const [x,y] of [[27,25],[32,26],[28,35],[33,36],[16,31],[39,31],[44,31],[21,33],[36,36]])tiles[y][x]='tree'}initWorld();
function blocked(x,y){return ['tree','water','wall'].includes(tileAt(x,y))}function enemyAt(x,y){return zombies.find(z=>z.hp>0&&z.x===x&&z.y===y)}function timeText(){const h=state.hour%24;return `${String(h%12||12).padStart(2,'0')}:00 ${h>=12?'PM':'AM'}`}
function addLog(text,important=false){state.logs.unshift({text,stamp:timeText(),important});state.logs=state.logs.slice(0,7);renderLog()}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>el.classList.remove('show'),1800)}
function addItem(n,c=1){state.inventory[n]=(state.inventory[n]||0)+c;renderInventory()}function removeItem(n,c=1){if((state.inventory[n]||0)<c)return false;state.inventory[n]-=c;if(!state.inventory[n])delete state.inventory[n];renderInventory();return true}
function renderInventory(){const el=document.getElementById('inventory'),entries=Object.entries(state.inventory);el.innerHTML=entries.length?entries.map(([n,c])=>{const it=state.items[n]||{icon:'◆',weight:.5};return `<div class="item-row" title="Click to use ${n}" data-item="${n}"><span class="item-icon">${it.icon}</span><span class="item-copy"><b>${n}</b><small>${(it.weight*c).toFixed(1)} kg · ${it.type}</small></span><span class="item-qty">×${c}</span></div>`}).join(''):'<div class="inventory-empty">Nothing but dust.</div>';el.querySelectorAll('.item-row').forEach(r=>r.addEventListener('click',()=>useItem(r.dataset.item)));const wt=Object.entries(state.inventory).reduce((a,[n,c])=>a+(state.items[n]?.weight||.5)*c,0);document.getElementById('weight-label').textContent=`${wt.toFixed(1)} / 22 kg`;document.querySelector('.weight-track i').style.width=`${Math.min(100,wt/22*100)}%`}
function renderLog(){document.getElementById('event-log').innerHTML=state.logs.map(x=>`<div class="log-line"><time>${x.stamp}</time><span>${x.important?'<b>!</b> ':''}${x.text}</span></div>`).join('')}
function renderNearby(){const items=[];for(const z of zombies){const d=Math.abs(z.x-player.x)+Math.abs(z.y-player.y);if(z.hp>0&&d<=8)items.push({d,icon:'♟',name:z.name,sub:'MOVING · HOSTILE',danger:true})}for(const l of loot){const d=Math.abs(l.x-player.x)+Math.abs(l.y-player.y);if(!l.opened&&d<=7)items.push({d,icon:l.icon,name:l.name,sub:d<=1?'WITHIN REACH':'SUPPLIES'})}items.sort((a,b)=>a.d-b.d);document.getElementById('nearby-count').textContent=String(items.length).padStart(2,'0');document.getElementById('nearby-list').innerHTML=items.length?items.slice(0,4).map(n=>`<div class="nearby-item"><span class="nearby-symbol" style="${n.danger?'color:#d77d69;background:#352924':''}">${n.icon}</span><span class="nearby-copy"><b>${n.name}</b><small>${n.sub}</small></span><span class="distance">${n.d}T</span></div>`).join(''):'<div class="empty-nearby">Nothing moving out there.</div>';const danger=items.some(x=>x.danger);document.querySelector('.threat-level b').textContent=`THREAT: ${danger?'HIGH':items.length>2?'MEDIUM':'LOW'}`;document.querySelectorAll('.threat-level i').forEach((b,i)=>b.style.background=danger&&i<3?'#d37b67':items.length>2&&i<2?'#d5a35b':i===0?'#738653':'#323d34')}
function renderVitals(){for(const [k,v] of [['health',player.hp],['stamina',player.stamina],['hunger',player.hunger],['thirst',player.thirst]]){document.getElementById(`${k}-value`).textContent=Math.round(v);document.getElementById(`${k}-meter`).style.width=`${Math.max(0,Math.min(100,v))}%`}document.getElementById('day-number').textContent=String(state.day).padStart(2,'0');document.getElementById('turn-number').textContent=String(state.turn+1).padStart(3,'0');document.getElementById('coords').textContent=`SECTOR 04 · ${timeText()}`;document.getElementById('survive-label').textContent=`DAY ${state.day} OF 7`;document.getElementById('survive-meter').style.width=`${Math.min(100,(state.day-1)/7*100+10)}%`;document.getElementById('condition').textContent=player.hp<30?'Badly wounded':player.thirst>75?'Dehydrated':player.hunger>75?'Starving':'Holding on'}
function updateAll(){renderVitals();renderInventory();renderNearby();draw()}
})();

