function spendTurn(kind='move'){if(state.dead||state.won||state.paused)return;state.turn++;state.day=Math.floor(state.turn/12)+1;state.hour=(12+(state.turn%12)*2)%24;player.hunger=Math.min(100,player.hunger+1.15);player.thirst=Math.min(100,player.thirst+1.8);player.stamina=Math.min(100,player.stamina+(kind==='rest'?28:kind==='attack'?1:4));if(player.hunger>=86||player.thirst>=86){player.hp=Math.max(0,player.hp-2);if(state.turn%3===0)addLog('Your body is failing. Find food and clean water.',true)}if(player.hp<=0){finish(false);return}zombiePhase();if(state.day>=8){finish(true);return}updateAll()}
function zombiePhase(){for(const z of zombies){if(z.hp<=0)continue;const dx=player.x-z.x,dy=player.y-z.y,d=Math.abs(dx)+Math.abs(dy);if(d===1){const damage=7+Math.floor(hash(state.turn,z.id)*7);player.hp=Math.max(0,player.hp-damage);addLog(`A shambler claws you for ${damage} damage.`,true);if(player.hp<=0){finish(false);return}continue}if(d>10||hash(state.turn,z.id*3)>.66)continue;const moves=Math.abs(dx)>=Math.abs(dy)?[[Math.sign(dx),0],[0,Math.sign(dy)],[0,-Math.sign(dy)]]:[[0,Math.sign(dy)],[Math.sign(dx),0],[-Math.sign(dx),0]];for(const [mx,my] of moves){const nx=z.x+mx,ny=z.y+my;if(nx===player.x&&ny===player.y||blocked(nx,ny)||enemyAt(nx,ny))continue;z.x=nx;z.y=ny;break}}}
function move(dx,dy){if(state.dead||state.won||state.paused)return;const nx=player.x+dx,ny=player.y+dy,z=enemyAt(nx,ny);if(z){attack(z);return}if(blocked(nx,ny)){toast('The way is blocked');return}player.x=nx;player.y=ny;spendTurn();document.getElementById('location-name').textContent=nx<27&&ny>34?'CORNER MARKET':'PINE RIDGE'}
function attack(z){if(state.dead||state.won||state.paused)return;let dmg=1+(state.inventory['Pocket knife']?1:0)+(state.inventory['Wooden spear']?2:0);if(player.stamina<15)dmg=Math.max(1,dmg-1);z.hp-=dmg;player.stamina=Math.max(0,player.stamina-8);addLog(`You strike the shambler for ${dmg} damage.`);if(z.hp<=0){state.killCount++;addLog('The shambler collapses into the weeds.');if(hash(z.x,z.y)>.45)setTimeout(()=>{if(!state.dead){addItem('Cloth');toast('Recovered: cloth')}},180)}spendTurn('attack')}
function search(){if(state.dead||state.won||state.paused)return;state.searches++;const found=state.searches<=5&&hash(state.searches,player.x+player.y)>.28;spendTurn();if(found){const drops=['Pine branch','Cloth','Scrap metal','Jerky'],item=drops[Math.floor(hash(player.x+state.searches,player.y)*drops.length)];addItem(item);addLog(`You search the undergrowth and find ${item.toLowerCase()}.`);toast(`FOUND: ${item.toUpperCase()}`)}else{addLog('You search the area. Nothing useful, just wind through the pines.');toast('Nothing found nearby.')}}
function interact(){if(state.dead||state.won||state.paused)return;const l=loot.find(x=>!x.opened&&Math.abs(x.x-player.x)<=1&&Math.abs(x.y-player.y)<=1);if(!l){toast('Nothing to interact with nearby');return}l.opened=true;spendTurn();let total=0;for(const [n,c] of Object.entries(l.contents)){addItem(n,c);total+=c}addLog(`You rummage through ${l.name.toLowerCase()} and take what you can.`,true);toast(`SUPPLIES FOUND · ${total} ITEMS`);renderNearby();draw()}
function rest(){if(state.dead||state.won||state.paused)return;spendTurn('rest');player.stamina=Math.min(100,player.stamina+30);if(player.hp<100&&player.hunger<70&&player.thirst<70)player.hp=Math.min(100,player.hp+3);addLog('You take a careful breather and listen for movement.');toast('You catch your breath.');updateAll()}

