const modalBackdrop=document.getElementById('modal-backdrop'),modalContent=document.getElementById('modal-content');
function showModal(title,body,actions=''){modalContent.innerHTML=`<p class="modal-eyebrow">AFTERFALL · FIELD RECORD</p><h2>${title}</h2><div class="modal-body">${body}</div>${actions?`<div class="modal-actions">${actions}</div>`:''}`;modalBackdrop.classList.remove('hidden');document.getElementById('modal-close').focus()}
function closeModal(){modalBackdrop.classList.add('hidden');if(!state.dead&&!state.won)state.paused=false;document.getElementById('pause-button').textContent='Ⅱ'}
function useItem(name){if(state.dead||state.won||state.paused)return;const item=state.items[name];if(!item||!state.inventory[name])return;let used=false,message='';if(item.type==='drink'){if(player.thirst<=8){toast('You are not thirsty right now');return}player.thirst=Math.max(0,player.thirst-38);message='You drink from a water bottle.';used=true}else if(item.type==='food'){if(player.hunger<=8){toast('You are not hungry right now');return}player.hunger=Math.max(0,player.hunger-(name==='Canned beans'?34:22));message=`You eat ${name.toLowerCase()}.`;used=true}else if(item.type==='heal'){if(player.hp>=100){toast('You are already in good health');return}player.hp=Math.min(100,player.hp+38);message='You dress your wounds with a bandage.';used=true}else{toast(item.type==='weapon'?'Weapons are used automatically in combat':'That item has no use right now');return}if(used){removeItem(name);addLog(message);spendTurn('rest');updateAll()}}
function eatBest(){const food=['Canned beans','Jerky'].find(n=>state.inventory[n]);if(food)useItem(food);else toast('No food in your pack')}
const recipes=[{name:'Wooden spear',desc:'A sturdy reach weapon. Greatly improves combat.',cost:{'Pine branch':2,'Scrap metal':1},output:1},{name:'Bandage',desc:'A clean wrap for wounds.',cost:{Cloth:2},output:1}];
function canCraft(r){return Object.entries(r.cost).every(([n,c])=>(state.inventory[n]||0)>=c)}
function craftItem(name){const recipe=recipes.find(r=>r.name===name);if(!recipe||!canCraft(recipe)){toast('Not enough materials');return}for(const [n,c] of Object.entries(recipe.cost))removeItem(n,c);addItem(recipe.name,recipe.output);addLog(`You craft ${recipe.name.toLowerCase()} from scavenged materials.`,true);spendTurn();updateAll();openCraft()}
function openCraft(){const body=recipes.map(r=>`<div class="recipe"><div><b>${r.name}</b><p>${r.desc}</p><small>NEEDS ${Object.entries(r.cost).map(([n,c])=>`${c} ${n}`).join(' · ')}</small></div><button data-craft="${r.name}" ${canCraft(r)?'':'disabled'}>CRAFT</button></div>`).join('');showModal('Crafting',`<p>Turn scavenged materials into tools that may keep you alive.</p>${body}`)}
function openJournal(){const body=`<p>Seven days. Find supplies, avoid unnecessary fights, and keep your body fed and hydrated until help arrives.</p><div class="journal-stats"><span>SHAMBLERS PUT DOWN <b>${state.killCount}</b></span><span>AREAS SEARCHED <b>${state.searches}</b></span><span>TIME IN THE COUNTY <b>${state.turn} TURNS</b></span></div><p class="modal-note">The county roads run east and west. Buildings and supply caches are marked on your map. Move beside a cache and press <b>E</b> to scavenge it.</p>`;showModal('Field journal',body)}
function openHelp(){showModal('Survivor handbook',`<p>Every action advances time. Shambling dead move when you do, and can attack from adjacent tiles. Make each turn count.</p><div class="control-list"><span><kbd>W A S D</kbd> / <kbd>↑ ↓ ← →</kbd><b>Move</b></span><span><kbd>E</kbd><b>Scavenge nearby cache</b></span><span><kbd>SPACE</kbd><b>Wait · <kbd>Q</kbd> search</b></span><span><kbd>Z</kbd><b>Rest · <kbd>F</kbd> eat / drink</b></span><span><kbd>C</kbd><b>Craft · <kbd>M</kbd> journal</b></span><span><kbd>ESC</kbd><b>Close / pause</b></span></div><p class="modal-note">Click inventory items to use food, water, or medical supplies. Weapons improve your automatic attacks.</p>`)}
function togglePause(){if(state.dead||state.won)return;if(state.paused){closeModal();return}state.paused=true;document.getElementById('pause-button').textContent='▶';showModal('Game paused',`<p>Take a moment. The county can wait.</p>`,`<button data-resume>RESUME SURVIVAL</button>`)}
function finish(won){if(state.dead||state.won)return;state.dead=!won;state.won=won;state.paused=true;document.querySelector('.portrait-status').textContent=won?'SAFE':'LOST';document.querySelector('.portrait-status').style.color=won?'#c0d889':'#cf6d60';const title=won?'You made it through.':'The long night took you.';const body=won?`<p>Seven days in the Quiet County—and you are still standing. Every supply found and every shambler defeated bought you another sunrise.</p><div class="journal-stats"><span>DAYS SURVIVED <b>7</b></span><span>SHAMBLERS PUT DOWN <b>${state.killCount}</b></span><span>AREAS SEARCHED <b>${state.searches}</b></span></div>`:`<p>Your journey ends on day ${Math.min(state.day,7)}. The county keeps its secrets, and the dead keep walking.</p><div class="journal-stats"><span>SHAMBLERS PUT DOWN <b>${state.killCount}</b></span><span>AREAS SEARCHED <b>${state.searches}</b></span><span>TURN REACHED <b>${state.turn}</b></span></div>`;showModal(title,body,'<button data-restart>START A NEW RUN</button>');updateAll()}
function performAction(action){if(action==='search')search();else if(action==='rest')rest();else if(action==='craft')openCraft();else if(action==='eat')eatBest();else if(action==='map')openJournal()}
function onKeyDown(e){if(e.key==='Escape'){if(!modalBackdrop.classList.contains('hidden'))closeModal();else togglePause();return}if(!modalBackdrop.classList.contains('hidden'))return;const key=e.key.toLowerCase(),moves={w:[0,-1],arrowup:[0,-1],s:[0,1],arrowdown:[0,1],a:[-1,0],arrowleft:[-1,0],d:[1,0],arrowright:[1,0]};if(moves[key]){e.preventDefault();move(...moves[key]);return}if(key===' '){e.preventDefault();spendTurn();return}if(key==='e')interact();else if(key==='q')search();else if(key==='z')rest();else if(key==='c')openCraft();else if(key==='f')eatBest();else if(key==='m')openJournal()}
